import { orcaCli } from './orca-cli.mjs'

// Host API 1.0's readContext names the focused workspace's branch and terminals but not its path.
// A terminal handle identifies the workspace exactly; branch plus name is the fallback when it has none.
// A workspace on a paired Orca server (a VPS) is not in this desktop's runtime at all: readContext then
// gives its repo's name, an empty branch and no terminals, so the paired servers are asked as well.
export async function resolveFocusedWorkspace(orca, { signal } = {}) {
  const context = await orca.host.call('workspace.readContext', {}, { signal })
  if (!context) return { context: null, path: null, via: 'none', candidates: [] }
  const [terminal] = context.terminals
  if (terminal) {
    const result = await orcaCli(['terminal', 'show', '--terminal', terminal.id], { signal })
    const path = (result.terminal ?? result).worktreePath
    if (path) return { context, path, via: 'terminal', candidates: [path] }
  }
  const { worktrees, hostScope } = await orcaCli(['worktree', 'list', '--limit', '500'], { signal })
  const candidates = matchWorktrees(worktrees, context).map((worktree) => worktree.path)
  if (candidates.length > 0 || context.terminals.length > 0) {
    return { context, path: candidates.length === 1 ? candidates[0] : null, via: 'branch', candidates }
  }
  return resolveOnServers(context, pairedServers(hostScope), { signal })
}

async function resolveOnServers(context, environments, { signal }) {
  const unreachable = []
  const found = await Promise.all(
    environments.map(async (environment) => {
      try {
        const [{ repos }, { worktrees }] = await Promise.all([
          orcaCli(['repo', 'list'], { signal, environment }),
          orcaCli(['worktree', 'list', '--limit', '500'], { signal, environment })
        ])
        return matchServerWorktrees(worktrees, repos, context).map((match) => ({ ...match, environment }))
      } catch (error) {
        unreachable.push(`${environment}: ${error.message}`)
        return []
      }
    })
  )
  return serverResolution(context, found.flat(), unreachable)
}

// Only the repo's name identifies a server's workspace, so a match counts only when it is the sole one
// and every server answered: a server that didn't may hold the focused workspace under the same name.
export function serverResolution(context, matches, unreachable = []) {
  const candidates = matches.map((match) => `${match.environment} ${match.worktree.path}`)
  if (matches.length !== 1 || unreachable.length > 0) return { context, path: null, via: 'server', candidates, unreachable }
  const [{ environment, worktree, repo }] = matches
  return {
    context,
    path: worktree.path,
    via: 'server',
    candidates,
    unreachable,
    server: { environment, branch: shortBranch(worktree.branch), repoUrl: repo?.gitRemoteIdentity?.remoteUrl ?? null }
  }
}

// Orca's CLI reports full refs; readContext reports short branch names.
export function shortBranch(ref = '') {
  return ref.replace(/^refs\/heads\//, '')
}

export function matchWorktrees(worktrees, { branch, displayName }) {
  return worktrees.filter(
    (worktree) =>
      !worktree.isArchived && shortBranch(worktree.branch) === branch && worktree.displayName === displayName
  )
}

// The paired Orca servers a local listing left out, by the name `--environment` takes. SSH hosts
// without a server of their own have no selector, and the CLI can't reach them.
export function pairedServers(hostScope) {
  return (hostScope?.omittedHostSelectors ?? [])
    .map((host) => /^--environment (.+)$/.exec(host.selector ?? '')?.[1])
    .filter(Boolean)
}

// A server's workspace reaches readContext with its repo's display name and no branch. Should Orca
// start sending the workspace's own name and branch, those match the way local ones do.
export function matchServerWorktrees(worktrees, repos, context) {
  const repoById = new Map(repos.map((repo) => [repo.id, repo]))
  return worktrees
    .filter((worktree) => !worktree.isArchived)
    .map((worktree) => ({ worktree, repo: repoById.get(worktree.repoId ?? worktree.id.split('::')[0]) }))
    .filter(({ worktree, repo }) =>
      context.branch
        ? shortBranch(worktree.branch) === context.branch && worktree.displayName === context.displayName
        : repo?.displayName === context.displayName
    )
}

// Orca forks this module in a Node worker on the desktop host and calls activate once. Orca starts it
// for a command, an event, or the panel's first plugin.request, and stops it after 5 idle minutes;
// the panel's next request starts it again.
import { actionRequest, runAction } from './actions.mjs'
import { connectionNotice, connectionReport } from './doctor.mjs'
import { createPanelData } from './panel.mjs'
import { collectSnapshot } from './snapshot.mjs'

// Entire writes its checkpoint data as an agent stops, so let it settle before reading.
const AGENT_SETTLE_MS = 3000

export default function activate(orca) {
  const notify = (notice, signal) =>
    orca.host.call('notifications.show', notice, { signal }).catch((error) => {
      console.error(`Notification failed: ${error.message}`)
    })

  // Tells open panels to ask for the data again. A post carries at most 256 KiB, so the data
  // itself goes back through the panel's request.
  const announce = () => {
    try {
      orca.panels?.post('entire.changed', {})
    } catch (error) {
      console.error(`Posting to the panel failed: ${error.message}`)
    }
  }

  // Each snapshot's report also goes to the plugin's Logs, since the command palette drops a
  // command's result.
  const collect = async (signal) => {
    const snapshot = await collectSnapshot(orca, { signal })
    console.log(connectionReport(orca, snapshot))
    return snapshot
  }

  // Only a read that found the workspace changed the data; a post after one that didn't would have the
  // panel fetch the old data and take it as news.
  const announceIfAdded = (snapshot) => {
    if (snapshot.workspace) announce()
    return snapshot
  }

  const panel = createPanelData({
    collect: () => collect().then(announceIfAdded),
    readContext: () => orca.host.call('workspace.readContext', {})
  })

  orca.panels?.handle('entire.data', async () => panel.data)
  orca.panels?.handle('entire.read', async (input) => panel.read({ maxAgeMs: Math.max(0, Number(input?.maxAgeMs) || 0) }))

  // Approve or merge the trail the panel showed in the workspace the click was in, then read Entire
  // again so the panel shows the result. Only the panel's confirmed click sends this; the worker never
  // acts on its own.
  orca.panels?.handle('entire.act', async (input) => {
    const request = actionRequest(input)
    let message
    try {
      message = await runAction(request, { data: panel.data })
    } catch (error) {
      console.error(`Trail ${request.action} #${request.trail} on ${request.branch} failed: ${error.message}`)
      throw error
    }
    console.log(message)
    // The action happened even if this read fails; the panel's next read catches up.
    const data = await panel.readAgain().catch((error) => {
      console.error(`Reading Entire after the ${request.action} failed: ${error.message}`)
      return panel.data
    })
    return { message, data }
  })

  // A command must answer within 30 seconds, so it reads on its own, under its own signal.
  async function refresh(signal) {
    const snapshot = announceIfAdded(panel.add(await collect(signal)))
    return connectionReport(orca, snapshot)
  }

  orca.commands.register('doctor', async (_args, { signal }) => {
    const report = await refresh(signal)
    await notify(connectionNotice(report), signal)
    return report
  })

  orca.commands.register('refresh', async (_args, { signal }) => {
    const report = await refresh(signal)
    const notice = connectionNotice(report)
    if (notice.title !== 'Entire: connected') await notify({ ...notice, title: 'Entire: panel updated with a problem' }, signal)
    return 'Panel updated'
  })

  // An agent finishing is when Entire has new checkpoints and sessions to show. Several finishing
  // together make one read.
  let timer = null
  orca.events.on('agent.status.changed', (event) => {
    if ((event.mainAgent?.state ?? event.state) !== 'done') return
    clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      panel.readAgain().catch((error) => console.error(`Refresh failed: ${error.message}`))
    }, AGENT_SETTLE_MS)
  })
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { matchServerWorktrees, matchWorktrees, pairedServers, serverResolution, shortBranch } from '../src/worker/workspace.mjs'

test("Orca CLI refs compare with readContext's short branch names", () => {
  assert.equal(shortBranch('refs/heads/feat/trails'), 'feat/trails')
  assert.equal(shortBranch('main'), 'main')
  assert.equal(shortBranch(''), '')
})

test('branch and name must both match, and archived workspaces never do', () => {
  const worktrees = [
    { path: 'a', branch: 'refs/heads/main', displayName: 'main' },
    { path: 'b', branch: 'refs/heads/main', displayName: 'api' },
    { path: 'c', branch: 'refs/heads/main', displayName: 'main', isArchived: true },
    { path: 'd', branch: '', displayName: 'main' }
  ]
  const matches = matchWorktrees(worktrees, { branch: 'main', displayName: 'main' })
  assert.deepEqual(
    matches.map((worktree) => worktree.path),
    ['a']
  )
})

test('paired servers come from the selectors a local listing left out', () => {
  const hostScope = {
    hostIds: ['local'],
    omittedHostIds: ['runtime:c9b8', 'ssh:ssh-1'],
    omittedHostSelectors: [
      { hostId: 'runtime:c9b8', selector: '--environment Endo VPS Server' },
      { hostId: 'ssh:ssh-1', selector: null }
    ]
  }
  assert.deepEqual(pairedServers(hostScope), ['Endo VPS Server'])
  assert.deepEqual(pairedServers(undefined), [])
  assert.deepEqual(pairedServers({ hostIds: ['local'], omittedHostIds: [] }), [])
})

// As `orca repo list` and `orca worktree list --environment "Endo VPS Server"` print them.
const repos = [
  { id: 'c78b', displayName: 'Endo VPS Server', gitRemoteIdentity: { remoteUrl: 'git@github.com:petercr/endo.chat_backend.git' } },
  { id: 'd735', displayName: 'leadgen' }
]
const worktrees = [
  { id: 'c78b::/home/ubuntu', displayName: 'fix/issue-620', branch: 'refs/heads/fix/issue-620', path: '/home/ubuntu' },
  { id: 'd735::/home/ubuntu/leadgen', repoId: 'd735', displayName: 'main', branch: 'refs/heads/main', path: '/home/ubuntu/leadgen' },
  { id: 'd735::/home/ubuntu/old', repoId: 'd735', displayName: 'old', branch: 'refs/heads/old', path: '/home/ubuntu/old', isArchived: true }
]

test("a server workspace matches by its repo's name, which is all readContext gives", () => {
  const [match, ...rest] = matchServerWorktrees(worktrees, repos, { displayName: 'Endo VPS Server', branch: '', terminals: [] })
  assert.equal(rest.length, 0)
  assert.equal(match.worktree.path, '/home/ubuntu')
  assert.equal(match.repo.gitRemoteIdentity.remoteUrl, 'git@github.com:petercr/endo.chat_backend.git')
  assert.deepEqual(
    matchServerWorktrees(worktrees, repos, { displayName: 'leadgen', branch: '', terminals: [] }).map((m) => m.worktree.path),
    ['/home/ubuntu/leadgen']
  )
  assert.deepEqual(matchServerWorktrees(worktrees, repos, { displayName: 'other', branch: '', terminals: [] }), [])
})

test('a server workspace with a branch matches by name and branch, like a local one', () => {
  assert.deepEqual(
    matchServerWorktrees(worktrees, repos, { displayName: 'main', branch: 'main', terminals: [] }).map((m) => m.worktree.path),
    ['/home/ubuntu/leadgen']
  )
  assert.deepEqual(matchServerWorktrees(worktrees, repos, { displayName: 'leadgen', branch: 'main', terminals: [] }), [])
})

test('a server match counts only when it is the only one and every server answered', () => {
  const context = { displayName: 'leadgen', branch: '', terminals: [] }
  const match = (environment) => ({ environment, worktree: worktrees[1], repo: repos[1] })
  const one = serverResolution(context, [match('VPS one')])
  assert.equal(one.path, '/home/ubuntu/leadgen')
  assert.deepEqual(one.server, { environment: 'VPS one', branch: 'main', repoUrl: null })
  // Another server with a leadgen of its own failed to answer: it may be the focused one.
  const partial = serverResolution(context, [match('VPS one')], ['VPS two: timed out'])
  assert.equal(partial.path, null)
  assert.equal(partial.server, undefined)
  assert.deepEqual(partial.candidates, ['VPS one /home/ubuntu/leadgen'])
  assert.equal(serverResolution(context, [match('VPS one'), match('VPS two')]).path, null)
  assert.equal(serverResolution(context, []).path, null)
})

// What the panel shows: the newest snapshot of each workspace the worker read, kept in the worker's
// memory. The panel asks for it with plugin.request (the handlers are in main.mjs) and gets all of
// it, then picks the focused workspace's entry itself (findEntry in panel/index.html).
import { reportLines } from './doctor.mjs'

const MAX_WORKSPACES = 10
// Orca refuses a plugin.request answer over 1 MiB; leave room for its envelope.
const MAX_ANSWER_CHARS = 900_000

export function panelEntry(snapshot) {
  return { ...snapshot, report: reportLines(snapshot) }
}

// Same path on the same host, or a terminal they share.
function sameWorkspace(entry, other) {
  const environment = (e) => e.workspace.server?.environment ?? null
  return (
    (entry.workspace.path && other.workspace.path === entry.workspace.path && environment(other) === environment(entry)) ||
    other.workspace.terminals.some((id) => entry.workspace.terminals.includes(id)) ||
    (!other.workspace.path && other.workspace.name === entry.workspace.name && other.workspace.branch === entry.workspace.branch)
  )
}

// A newer entry replaces any for the same workspace, and the oldest go once the answer gets too big.
export function mergeEntry(data, entry, { maxChars = MAX_ANSWER_CHARS } = {}) {
  const others = (data?.workspaces ?? []).filter((other) => !sameWorkspace(entry, other))
  const workspaces = [entry, ...others].slice(0, MAX_WORKSPACES)
  while (workspaces.length > 1 && JSON.stringify(workspaces).length > maxChars) workspaces.pop()
  return { version: 1, workspaces }
}

// The entry the panel shows for a readContext result. Keep this the same as findEntry in
// panel/index.html: the worker uses it to tell whether the panel's entry is fresh enough.
export function findShown(data, context) {
  const list = data?.workspaces ?? []
  const ids = context.terminals.map((terminal) => terminal.id)
  // A workspace keeps its terminals when it switches branch, so the branch has to match as well.
  const byTerminal = list.find((entry) => entry.workspace.branch === context.branch && entry.workspace.terminals.some((id) => ids.includes(id)))
  if (byTerminal) return byTerminal
  // Many repos share a name and branch such as main/main: only when terminals can't tell them apart
  // and exactly one entry matches.
  const byName = list.filter(
    (entry) =>
      !(ids.length > 0 && entry.workspace.terminals.length > 0) && entry.workspace.name === context.displayName && entry.workspace.branch === context.branch
  )
  return byName.length === 1 ? byName[0] : null
}

// The panel's data and the reads that fill it. `collect` reads Entire for the focused workspace (a
// snapshot), `readContext` asks Orca which workspace that is. One read runs at a time: a request
// that finds one running waits for it, and reads again only if focus moved meanwhile.
export function createPanelData({ collect, readContext, now = Date.now }) {
  let data = null
  let reading = null

  function add(snapshot) {
    if (snapshot.workspace) data = mergeEntry(data, panelEntry(snapshot))
    return snapshot
  }

  // A read outlives the request that started it, since others may be waiting on it, so it takes no
  // signal; Entire's own timeouts bound it.
  function readNow() {
    reading ??= collect().then(add).finally(() => {
      reading = null
    })
    return reading
  }

  // A read that couldn't find the focused workspace (its lookup failed) added nothing, so answering
  // with the data would pass the old data off as this read's. Fail instead: the panel shows why and
  // retries on its schedule.
  async function readFresh() {
    const snapshot = await readNow()
    if (!snapshot.workspace) throw new Error(snapshot.problem ?? 'Entire was read for no workspace')
    return data
  }

  async function shown() {
    const context = await readContext()
    return context ? findShown(data, context) : null
  }

  return {
    get data() {
      return data
    },
    add,
    // Reads Entire unless the panel's entry for the focused workspace is younger than maxAgeMs (0
    // always reads), and answers with all the data.
    async read({ maxAgeMs = 0 } = {}) {
      if (maxAgeMs > 0) {
        const at = Date.parse((await shown())?.at)
        if (Number.isFinite(at) && now() - at < maxAgeMs) return data
      }
      if (reading) {
        const joined = await reading.catch(() => null)
        if (joined && (await shown())?.at === joined.at) return data
      }
      return readFresh()
    },
    // Reads Entire with a read that starts now: one already running may have begun before what the
    // caller wants to see, such as an agent's last checkpoint, so it waits for that one and reads again.
    async readAgain() {
      if (reading) await reading.catch(() => null)
      return readFresh()
    }
  }
}

