function footer(entry) {
  return add(
    el('footer'),
    document.createTextNode('Checks Entire when you switch here, when an agent finishes and every 5 minutes. To check now, use ↻ or '),
    el('b', null, 'Entire: Refresh panel'),
    document.createTextNode('.'),
    el('br'),
    reportButton(entry)
  )
}

function rerender() {
  shown = null
  render(last.context, last.error)
}

function render(context, error) {
  last = { context: context, error: error }
  var entry = context ? findEntry(context) : null
  noteFocus(context, entry)
  var problem = readError && readError.code + ': ' + readError.message
  var signature = JSON.stringify([context, entry && entry.at, error && error.code, reads, refreshing, problem, armed, acting, outcome, Math.floor(Date.now() / 60000)])
  if (signature === shown) return
  shown = signature
  root.textContent = ''

  if (error) return add(root, blank("Can't read the workspace", error.code + ': ' + error.message), footer())
  if (!context) return add(root, blank('No workspace focused', 'Focus a workspace to see its Entire data.'), footer())
  add(root, header(context, entry))
  if (problem) add(root, el('div', 'notice bad', "Couldn't read Entire: " + problem))
  if (!entry) {
    return add(
      root,
      reads > 0
        ? blank('Reading Entire for this workspace…', 'This takes a few seconds, longer for a WSL workspace or one on a paired server.')
        : blank('No Entire data yet', 'Use ↻ to read Entire for this workspace.'),
      footer()
    )
  }
  var status = entry.data.status
  if (status) add(root, chips(status))
  notices(entry).forEach(function (notice) {
    add(root, notice)
  })
  if (!entry.steps.length) return add(root, footer(entry))

  var active = (status && status.active_sessions) || []
  if (active.length) add(root, section('sessions', 'Sessions', String(active.length), sessions(status), true))
  else if (!status) add(root, unread(step(entry, 'status')))
  var value = entry.data.trail
  add(root, section('trail', value && value.number ? 'Trail #' + value.number : 'Trail', trailBadge(value), trail(entry), true))
  var list = entry.data.checkpoints
  add(root, section('checkpoints', 'Checkpoints', list ? String(list.length) : '', list ? checkpoints(list) : unread(step(entry, 'checkpoints')), false))
  var bad = failing(entry)
  add(root, section('connection', 'Connection', el('span', 'count ' + (bad ? 'bad' : 'ok'), bad ? 'Problem' : 'OK'), connection(entry), bad), footer(entry))
}

// When the panel mounts and when focus moves to another workspace or branch, it asks the worker for
// data, which reads Entire only if what it has for the workspace is over a minute old. The
// minute's rerender asks again once the shown entry is 5 minutes old, and retries a failed read
// as often. With no entry it asks every 5 minutes whatever the last answer was, and at once if
// nothing was asked about this workspace since focus came here: another branch of the same
// checkout shares its path, so a read of that branch still running at the switch replaces this
// branch's entry when it lands.
function noteFocus(context, entry) {
  var key = context
    ? JSON.stringify([
        context.displayName,
        context.branch,
        context.terminals
          .map(function (terminal) {
            return terminal.id
          })
          .sort()
      ])
    : null
  var age = entry ? Date.now() - Date.parse(entry.at) : Infinity
  if (key !== focusedKey) {
    focusedKey = key
    readError = null
    // A confirmation waiting from another workspace mustn't carry over; a result may stay, since
    // it names its trail and shows only there.
    armed = null
    if (key && !(age < SWITCH_FRESH_MS)) ask(SWITCH_FRESH_MS)
    return
  }
  if (!key || reads > 0) return
  var due = !(Date.now() - asked.at < AUTO_REFRESH_MS)
  if (entry) {
    if (due && !(age < AUTO_REFRESH_MS)) ask(AUTO_REFRESH_MS)
  } else if (asked.key !== key || due) {
    ask(SWITCH_FRESH_MS)
  }

